import subprocess
from ipaddress import IPv4Network
def task_func(ip_range):
    result = {}
    network = IPv4Network(ip_range)
    for ip in network:
        ip_str = str(ip)
        try:
            subprocess.run(['ping', '-c', '1', '-W', '1', ip_str], capture_output=True, check=True)
            result[ip_str] = True
        except subprocess.CalledProcessError:
            result[ip_str] = False
    return result

import subprocess
import psutil
import time
def task_func(process_name: str) -> str:
    running = any(p.name() == process_name for p in psutil.process_iter())
    if not running:
        subprocess.Popen(process_name, shell=True)
        return f"Process not found. Starting {process_name}."
    else:
        for proc in psutil.process_iter():
            if proc.name() == process_name:
                proc.terminate()
                time.sleep(0.5)
                break
        subprocess.Popen(process_name, shell=True)
        return f"Process found. Restarting {process_name}."

import subprocess
import platform
import time
def task_func(url):
    if platform.system() == 'Windows':
        startupinfo = subprocess.STARTUPINFO()
        startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW
        process = subprocess.Popen(['cmd', '/c', 'start', url], startupinfo=startupinfo, shell=True)
    elif platform.system() == 'Darwin':
        process = subprocess.Popen(['open', url], shell=True)
    else:
        process = subprocess.Popen(['xdg-open', url], shell=True)
    time.sleep(1)
    return process.poll()

import subprocess
import time
import threading
def task_func(file_list):
    if not isinstance(file_list, list):
        raise TypeError("file_list must be a list")
    processes = []
    def run_file(filepath):
        try:
            proc = subprocess.Popen(filepath, shell=True)
            processes.append(proc)
        except Exception:
            processes.append(None)
    threads = []
    for f in file_list:
        if not isinstance(f, str):
            raise TypeError("Each file path must be a string")
        t = threading.Thread(target=run_file, args=(f,))
        t.start()
        threads.append(t)
    for t in threads:
        t.join()
    exit_codes = []
    for proc in processes:
        if proc is None:
            exit_codes.append(-1)
        else:
            proc.wait()
            exit_codes.append(proc.returncode)
    return exit_codes

import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    if not os.path.exists(src_folder) or not os.path.exists(dst_folder):
        return {'success': False, 'message': 'Source or destination folder does not exist', 'failed_files': []}
    files = glob(os.path.join(src_folder, '*'))
    failed_files = []
    for file in files:
        if os.path.isfile(file):
            dst_file = os.path.join(dst_folder, os.path.basename(file) + '.gz')
            try:
                subprocess.run(['gzip', '-c', file], stdout=open(dst_file, 'wb'), check=True)
            except subprocess.CalledProcessError:
                failed_files.append(os.path.basename(file))
                continue
            try:
                shutil.move(dst_file, os.path.join(dst_folder, os.path.basename(dst_file)))
            except shutil.Error:
                failed_files.append(os.path.basename(file))
    success = len(failed_files) == 0
    message = 'All files compressed and moved successfully' if success else 'Some files failed to compress or move'
    return {'success': success, 'message': message, 'failed_files': failed_files}

import subprocess
import logging
def task_func(filepath):
    logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
    try:
        result = subprocess.run(['g++', filepath, '-o', filepath.replace('.cpp', '')], capture_output=True, text=True, check=True)
        logging.info('Compilation successful: ' + result.stdout)
    except subprocess.CalledProcessError as e:
        logging.error('Compilation failed: ' + e.stderr)
        raise
    except FileNotFoundError:
        logging.error('Compiler not found or file does not exist')
        raise
